/**
 * Gets the current theme string based on the app's color scheme.
 * Used consistently across account card components.
 */
@Composable
private fun getAccountCardTheme(): String {
    val scheme = LocalAppColorScheme.current
    return when (scheme.background) {
        BackgroundAmoled -> "Amoled"
        BackgroundDark -> "Dark"
        else -> "Light"
    }
}

@Composable
fun AeonAccountCardSmall(
    account: Account,
    balance: BigDecimal,
    balanceInBase: BigDecimal,
    baseCurrency: String,
    currencyBalances: Map<String, BigDecimal> = emptyMap(),
    onClick: () -> Unit,
